module SDFBBN (CLK_N, D, RESET_B, SCD, SCE, SET_B, Q, Q_N);
  input CLK_N, D, RESET_B, SCD, SCE, SET_B;
  output Q, Q_N;
  reg IQ;
  wire IQ_N = ~IQ;
  always @(negedge CLK_N or negedge RESET_B or negedge SET_B)
    if (~RESET_B) IQ <= 1'b0;
